export class TaskPoolClosedError extends Error {
  constructor(message = "Task pool is closed") {
    super(message);
    this.name = "TaskPoolClosedError";
  }
}

export class TaskPoolTimeoutError extends Error {
  constructor(taskId) {
    super(`Task timed out: ${taskId}`);
    this.name = "TaskPoolTimeoutError";
    this.taskId = taskId;
  }
}

function abortError() {
  const error = new Error("The operation was aborted");
  error.name = "AbortError";
  return error;
}

function isObject(value) {
  return value !== null && typeof value === "object";
}

function assertPositiveSafeInteger(value, name) {
  if (!Number.isSafeInteger(value) || value <= 0) {
    throw new TypeError(`${name} must be a positive safe integer`);
  }
}

function assertNonNegativeSafeInteger(value, name) {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new TypeError(`${name} must be a non-negative safe integer`);
  }
}

export class AsyncTaskPool {
  #concurrency;
  #perKeyConcurrency;
  #agingMs;
  #now;
  #closed = false;
  #queue = [];
  #reserved = new Set();
  #keyActive = new Map();
  #active = 0;
  #sequence = 0;
  #pumping = false;
  #idleWaiters = [];
  #submitted = 0;
  #started = 0;
  #succeeded = 0;
  #failed = 0;
  #aborted = 0;
  #timedOut = 0;
  #maxActive = 0;

  constructor(options) {
    if (!isObject(options)) {
      throw new TypeError("options must be an object");
    }

    const {
      concurrency,
      perKeyConcurrency = 1,
      agingMs = 100,
      now = Date.now,
    } = options;

    assertPositiveSafeInteger(concurrency, "concurrency");
    assertPositiveSafeInteger(perKeyConcurrency, "perKeyConcurrency");
    assertNonNegativeSafeInteger(agingMs, "agingMs");
    if (typeof now !== "function") {
      throw new TypeError("now must be a function");
    }

    this.#concurrency = concurrency;
    this.#perKeyConcurrency = perKeyConcurrency;
    this.#agingMs = agingMs;
    this.#now = now;
  }

  schedule(options) {
    if (this.#closed) {
      throw new TaskPoolClosedError();
    }
    if (!isObject(options)) {
      throw new TypeError("task options must be an object");
    }

    const {
      id,
      key = "default",
      priority = 0,
      timeoutMs,
      signal,
      run,
    } = options;

    if (typeof id !== "string" || id.length === 0) {
      throw new TypeError("id must be a non-empty string");
    }
    if (typeof key !== "string" || key.length === 0) {
      throw new TypeError("key must be a non-empty string");
    }
    if (typeof priority !== "number" || !Number.isFinite(priority)) {
      throw new TypeError("priority must be finite");
    }
    if (typeof run !== "function") {
      throw new TypeError("run must be a function");
    }
    if (timeoutMs !== undefined) {
      assertPositiveSafeInteger(timeoutMs, "timeoutMs");
    }

    const callerSignal = signal === null ? undefined : signal;
    if (callerSignal !== undefined) {
      if (!isObject(callerSignal)
        || typeof callerSignal.addEventListener !== "function"
        || typeof callerSignal.removeEventListener !== "function"
        || typeof callerSignal.aborted !== "boolean") {
        throw new TypeError("signal must be an AbortSignal");
      }
    }
    if (this.#reserved.has(id)) {
      throw new Error(`Task ID is already reserved: ${id}`);
    }

    const submittedAt = this.#readClock();
    let resolvePromise;
    let rejectPromise;
    const promise = new Promise((resolve, reject) => {
      resolvePromise = resolve;
      rejectPromise = reject;
    });

    const task = {
      id,
      key,
      priority,
      timeoutMs,
      timeoutRemaining: timeoutMs,
      callerSignal,
      abortListener: null,
      controller: new AbortController(),
      run,
      submittedAt,
      sequence: this.#sequence++,
      state: "queued",
      callerSettled: false,
      terminalRecorded: false,
      resolve: resolvePromise,
      reject: rejectPromise,
      timeoutHandle: null,
    };

    this.#reserved.add(id);
    this.#submitted += 1;
    this.#queue.push(task);

    if (callerSignal !== undefined) {
      task.abortListener = () => this.#handleAbort(task);
      callerSignal.addEventListener("abort", task.abortListener, { once: true });
      if (callerSignal.aborted) {
        this.#cancelQueued(task, abortError(), false);
      }
    }

    if (task.state === "queued") {
      this.#pump();
    }
    return promise;
  }

  close(options = {}) {
    if (!isObject(options)) {
      throw new TypeError("close options must be an object");
    }

    this.#closed = true;
    if (options.abortQueued === true) {
      const queued = [...this.#queue];
      for (const task of queued) {
        this.#cancelQueued(task, new TaskPoolClosedError(), false);
      }
    }
    this.#pump();
    this.#resolveIdle();
  }

  whenIdle() {
    if (this.#queue.length === 0 && this.#active === 0) {
      return Promise.resolve();
    }
    return new Promise((resolve) => {
      this.#idleWaiters.push(resolve);
    });
  }

  metrics() {
    return Object.freeze({
      queued: this.#queue.length,
      active: this.#active,
      submitted: this.#submitted,
      started: this.#started,
      succeeded: this.#succeeded,
      failed: this.#failed,
      aborted: this.#aborted,
      timedOut: this.#timedOut,
      maxActive: this.#maxActive,
    });
  }

  #readClock() {
    const value = this.#now();
    if (!Number.isFinite(value)) {
      throw new TypeError("now must return a finite number");
    }
    return value;
  }

  #effectivePriority(task, currentTime) {
    if (this.#agingMs === 0) {
      return task.priority;
    }
    const waitedMs = Math.max(0, currentTime - task.submittedAt);
    return task.priority + Math.floor(waitedMs / this.#agingMs);
  }

  #pump() {
    if (this.#pumping) {
      return;
    }

    this.#pumping = true;
    try {
      while (this.#active < this.#concurrency && this.#queue.length > 0) {
        const currentTime = this.#agingMs === 0 ? 0 : this.#readClock();
        let selectedIndex = -1;
        let selectedPriority = -Infinity;

        for (let index = 0; index < this.#queue.length; index += 1) {
          const task = this.#queue[index];
          if (task.state !== "queued") {
            continue;
          }
          if ((this.#keyActive.get(task.key) ?? 0) >= this.#perKeyConcurrency) {
            continue;
          }
          const effectivePriority = this.#effectivePriority(task, currentTime);
          if (selectedIndex === -1 || effectivePriority > selectedPriority) {
            selectedIndex = index;
            selectedPriority = effectivePriority;
          }
        }

        if (selectedIndex === -1) {
          break;
        }
        const [task] = this.#queue.splice(selectedIndex, 1);
        this.#start(task);
      }
    } finally {
      this.#pumping = false;
    }
    this.#resolveIdle();
  }

  #start(task) {
    task.state = "running";
    this.#active += 1;
    this.#started += 1;
    const keyCount = this.#keyActive.get(task.key) ?? 0;
    this.#keyActive.set(task.key, keyCount + 1);
    this.#maxActive = Math.max(this.#maxActive, this.#active);
    if (task.timeoutMs !== undefined) {
      this.#armTimeout(task);
    }

    let result;
    try {
      result = task.run(task.controller.signal);
    } catch (error) {
      this.#underlyingSettled(task, false, error);
      return;
    }
    Promise.resolve(result).then(
      (value) => this.#underlyingSettled(task, true, value),
      (error) => this.#underlyingSettled(task, false, error),
    );
  }

  #armTimeout(task) {
    const delay = Math.min(task.timeoutRemaining, 2_147_483_647);
    task.timeoutRemaining -= delay;
    task.timeoutHandle = setTimeout(() => {
      task.timeoutHandle = null;
      if (task.state !== "running" || task.callerSettled) {
        return;
      }
      if (task.timeoutRemaining > 0) {
        this.#armTimeout(task);
        return;
      }
      this.#terminateActive(task, "timedOut", new TaskPoolTimeoutError(task.id));
    }, delay);
  }

  #handleAbort(task) {
    if (task.state === "queued") {
      this.#cancelQueued(task, abortError());
    } else if (task.state === "running") {
      this.#terminateActive(task, "aborted", abortError());
    }
  }

  #cancelQueued(task, error, shouldPump = true) {
    if (task.state !== "queued") {
      return;
    }
    this.#removeQueued(task);
    task.state = "settled";
    this.#cleanupListener(task);
    this.#reserved.delete(task.id);
    if (!task.controller.signal.aborted) {
      task.controller.abort(error);
    }
    this.#recordTerminal(task, "aborted");
    this.#settleCaller(task, false, error);
    if (shouldPump) {
      this.#pump();
    }
    this.#resolveIdle();
  }

  #terminateActive(task, classification, error) {
    if (task.state !== "running" || task.callerSettled) {
      return;
    }
    this.#recordTerminal(task, classification);
    this.#settleCaller(task, false, error);
    if (!task.controller.signal.aborted) {
      task.controller.abort(error);
    }
  }

  #underlyingSettled(task, succeeded, value) {
    if (task.state !== "running") {
      return;
    }
    this.#clearTimeout(task);
    this.#cleanupListener(task);
    task.state = "settled";
    this.#active -= 1;
    const keyCount = (this.#keyActive.get(task.key) ?? 1) - 1;
    if (keyCount === 0) {
      this.#keyActive.delete(task.key);
    } else {
      this.#keyActive.set(task.key, keyCount);
    }
    this.#reserved.delete(task.id);

    if (!task.callerSettled) {
      this.#recordTerminal(task, succeeded ? "succeeded" : "failed");
      this.#settleCaller(task, succeeded, value);
    }
    this.#pump();
    this.#resolveIdle();
  }

  #recordTerminal(task, classification) {
    if (task.terminalRecorded) {
      return;
    }
    task.terminalRecorded = true;
    switch (classification) {
      case "succeeded":
        this.#succeeded += 1;
        break;
      case "failed":
        this.#failed += 1;
        break;
      case "aborted":
        this.#aborted += 1;
        break;
      case "timedOut":
        this.#timedOut += 1;
        break;
      default:
        throw new Error(`Unknown terminal classification: ${classification}`);
    }
  }

  #settleCaller(task, succeeded, value) {
    if (task.callerSettled) {
      return;
    }
    task.callerSettled = true;
    if (succeeded) {
      task.resolve(value);
    } else {
      task.reject(value);
    }
  }

  #removeQueued(task) {
    const index = this.#queue.indexOf(task);
    if (index !== -1) {
      this.#queue.splice(index, 1);
    }
  }

  #cleanupListener(task) {
    if (task.callerSignal !== undefined && task.abortListener !== null) {
      task.callerSignal.removeEventListener("abort", task.abortListener);
      task.abortListener = null;
    }
  }

  #clearTimeout(task) {
    if (task.timeoutHandle !== null) {
      clearTimeout(task.timeoutHandle);
      task.timeoutHandle = null;
    }
  }

  #resolveIdle() {
    if (this.#queue.length !== 0 || this.#active !== 0 || this.#idleWaiters.length === 0) {
      return;
    }
    const waiters = this.#idleWaiters.splice(0);
    for (const resolve of waiters) {
      resolve();
    }
  }
}
